function getThemeMeta(themeId) {
    if (!themeId) themeId = 'fox';
    let normalized = String(themeId).toLowerCase().trim();

    // Normalización de compatibilidad hacia atrás
    if (normalized === 'dark') normalized = 'fox';
    if (normalized === 'light') normalized = 'rabbit';

    const match = NATEX_THEMES.find(t => t.id === normalized);
    if (match) return match;

    if (normalized === 'custom') {
        const custom = NATEX_THEMES.find(t => t.id === 'custom');
        if (custom) return custom;
    }

    // Predeterminado al tema clásico (fox)
    return NATEX_THEMES[0];
}

/**
 * Actualiza todos los elementos de mascota en el DOM (.theme-mascot-icon y .fox-illustration)
 * con el icono vectorial SVG del tema activo y actualiza el título del documento.
 * @param {string} [themeId] - ID del tema activo opcional. Si no se pasa, lo lee del DOM.
 */
function updateThemeMascotIcons(themeId) {
    if (typeof document === 'undefined') return;

    if (!themeId) {
        themeId = document.documentElement.getAttribute('data-theme') ||
                  (typeof currentTheme !== 'undefined' ? currentTheme : 'fox');
    }

    const meta = getThemeMeta(themeId);
    if (!meta) return;

    const isEn = (typeof currentLanguage !== 'undefined' && currentLanguage === 'en');
    const themeName = isEn ? meta.name_en : meta.name_es;

    // Actualiza todas las instancias de .theme-mascot-icon
    const mascotIcons = document.querySelectorAll('.theme-mascot-icon');
    mascotIcons.forEach(el => {
        el.innerHTML = meta.svg;
        el.setAttribute('data-active-theme', meta.id);
        el.setAttribute('title', `${meta.emojiFallback} ${themeName}`);
    });

    // Actualiza la ilustración de bienvenida / splash (.fox-illustration)
    const illustrations = document.querySelectorAll('.fox-illustration');
    illustrations.forEach(el => {
        el.innerHTML = meta.svg;
        el.setAttribute('data-active-theme', meta.id);
        el.setAttribute('title', themeName);
    });

    // Actualiza el título del documento
    try {
        document.title = `NaTex Studio — ${themeName}`;
    } catch (e) {
        // Ignorar en entornos sin soporte para document.title
    }
}

/**
 * Renderiza la cuadrícula de selección de temas en #themeSelectorGrid (o contenedor provisto).
 * Genera tarjetas interactivas .theme-card-option para los 20 temas + custom y vincula
 * el evento click con applyTheme(t.id).
 * @param {string} [activeThemeId] - ID del tema seleccionado actualmente
 * @param {HTMLElement|string} [container] - Contenedor opcional o su ID (por defecto #themeSelectorGrid)
 */
function renderThemeSelectorGrid(activeThemeId, container) {
    if (typeof document === 'undefined') return;

    let targetGrid = null;
    if (typeof container === 'string') {
        targetGrid = document.getElementById(container);
    } else if (container && container.nodeType === 1) {
        targetGrid = container;
    } else {
        targetGrid = document.getElementById('themeSelectorGrid');
    }

    if (!targetGrid) return;

    if (!activeThemeId) {
        activeThemeId = document.documentElement.getAttribute('data-theme') ||
                        (typeof currentTheme !== 'undefined' ? currentTheme : 'fox');
    }

    const currentMeta = getThemeMeta(activeThemeId);
    const normalizedActive = currentMeta.id;
    const isEn = (typeof currentLanguage !== 'undefined' && currentLanguage === 'en');

    targetGrid.innerHTML = '';

    NATEX_THEMES.forEach(t => {
        const card = document.createElement('div');
        card.className = 'theme-card-option';
        card.setAttribute('data-theme', t.id);

        const isActive = (t.id === normalizedActive) ||
                         (t.id === 'fox' && activeThemeId === 'dark') ||
                         (t.id === 'rabbit' && activeThemeId === 'light') ||
                         (t.id === 'custom' && activeThemeId === 'custom');

        if (isActive) {
            card.classList.add('active');
        }

        const displayName = isEn ? t.name_en : t.name_es;
        const modeLabel = isEn ? (t.mode === 'light' ? 'Light' : 'Dark') : (t.mode === 'light' ? 'Claro' : 'Oscuro');

        card.innerHTML = `
            <div class="theme-card-mascot theme-card-icon" style="color: ${t.accent};">
                ${t.svg}
            </div>
            <span class="theme-card-name">${displayName}</span>
            <div class="theme-card-meta">
                <span class="theme-card-badge" style="background-color: ${t.accent};"></span>
                <span class="theme-card-mode">${modeLabel}</span>
            </div>
        `;

        card.addEventListener('click', () => {
            targetGrid.querySelectorAll('.theme-card-option').forEach(c => c.classList.remove('active'));
            card.classList.add('active');

            if (typeof applyTheme === 'function') {
                applyTheme(t.id);
            } else {
                document.documentElement.setAttribute('data-theme', t.id);
                try {
                    localStorage.setItem('natex_theme', t.id);
                } catch (e) {}
            }
            updateThemeMascotIcons(t.id);
        });

        targetGrid.appendChild(card);
    });
}

// Exposición en el entorno global (Window)
if (typeof window !== 'undefined') {
    window.NATEX_THEMES = NATEX_THEMES;
    window.getThemeMeta = getThemeMeta;
    window.updateThemeMascotIcons = updateThemeMascotIcons;
    window.renderThemeSelectorGrid = renderThemeSelectorGrid;

    // Observador automático de mutaciones en data-theme sobre <html>
    if (typeof MutationObserver !== 'undefined' && typeof document !== 'undefined') {
        const themeObserver = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                if (mutation.type === 'attributes' && mutation.attributeName === 'data-theme') {
                    const newTheme = document.documentElement.getAttribute('data-theme');
                    updateThemeMascotIcons(newTheme);
                }
            }
        });

        const initCatalogEngine = () => {
            if (document.documentElement) {
                themeObserver.observe(document.documentElement, {
                    attributes: true,
                    attributeFilter: ['data-theme']
                });
            }
            const active = document.documentElement.getAttribute('data-theme') ||
                           (typeof currentTheme !== 'undefined' ? currentTheme : 'fox');
            updateThemeMascotIcons(active);
            renderThemeSelectorGrid(active);
        };

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initCatalogEngine);
        } else {
            initCatalogEngine();
        }
    }
}

// Compatibilidad con módulos Node / CommonJS si se requiere
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        NATEX_THEMES,
        getThemeMeta,
        updateThemeMascotIcons,
        renderThemeSelectorGrid
    };
}
